import { Node, Project, SyntaxKind } from 'ts-morph';

/**
 * Converts an object-literal source string into a plain JavaScript value.
 *
 * The string is parsed in a throwaway ts-morph project as `const obj = ...`.
 * Object literals become plain objects, arrays become arrays of converted
 * elements, string and numeric literals are unwrapped, `true`, `false` and
 * `null` map to their runtime values, and any other node (identifier or
 * expression) is kept as its source text.
 *
 * @param objString - Source text of an object literal.
 * @returns The converted value, or `null` when parsing fails or the
 *   initializer is not an object literal.
 */
/**
 * parseObject variable - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
export const parseObject = (objString: string): any => {
  try {
    const project = new Project();

    // Créer un fichier temporaire avec l'objet
    const tempFile = project.createSourceFile(
      'temp.ts',
      `
/**
 * obj const - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
      const obj = ${objString};
      export default obj;
    `,
    );

    // Obtenir la déclaration de variable
    const variableDeclaration = tempFile.getVariableDeclaration('obj');
    if (!variableDeclaration) return null;

    const initializer = variableDeclaration.getInitializer();
    if (
      !initializer ||
      initializer.getKind() !== SyntaxKind.ObjectLiteralExpression
    ) {
      return null;
    }

    // Fonction récursive pour parser l'objet
    /**
     * Recursively converts a ts-morph node into a plain JavaScript value.
     *
     * @param node - Node visited during the conversion.
     * @returns Converted value, falling back to the node's source text for
     *   unsupported nodes.
     */
    const parseNode = (node: Node): any => {
      if (Node.isObjectLiteralExpression(node)) {
/**
 * obj const - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
        const obj: any = {};
        node.getProperties().forEach((prop: any) => {
          if (Node.isPropertyAssignment(prop)) {
            const name = prop.getName();
            const initializer = prop.getInitializer();
            if (initializer) {
              const value = parseNode(initializer);
              obj[name] = value;
            }
          }
        });
        return obj;
      }

      if (Node.isArrayLiteralExpression(node)) {
        return node.getElements().map((element: any) => parseNode(element));
      }

      if (Node.isStringLiteral(node) || Node.isNumericLiteral(node)) {
        return node.getLiteralValue();
      }

      if (Node.isTrueLiteral(node)) {
        return true;
      }

      if (Node.isFalseLiteral(node)) {
        return false;
      }

      if (Node.isNullLiteral(node)) {
        return null;
      }

      if (Node.isIdentifier(node)) {
        return node.getText();
      }

      return node.getText();
    };

    return parseNode(initializer);
  } catch (error) {
    console.error('Erreur avec ts-morph:', error);
    return null;
  }
};

features/typescript/resolveType.text:
import { SymbolFlags, TypeFormatFlags, SourceFile, Type } from 'ts-morph';

/**
 * Resolves a ts-morph {@linkcode Type} to a readable textual representation.
 *
 * Strategies are attempted in order and the first candidate that differs from
 * `type.getText()`, contains no `import(...)` reference and is structurally
 * descriptive is returned: full compiler formatting, alias or imported-type
 * resolution, the `getApparentType` view, then a forced structural expansion.
 * When no candidate qualifies, or when the compiler throws, the type's own text
 * is returned.
 *
 * @param sourceFile - Source file providing the project and type checker.
 * @param type - Type to turn into text.
 * @returns The resolved type text, or `type.getText()` as a fallback.
 */
/**
 * resolveType variable - Auto-generated expression
 * 
 * ⚠️ WARNING: This expression is auto-generated and should not be modified.
 * Any manual changes will be overwritten during the next generation.
 * 
 * @generated
 * @readonly
 * @author chlbri (bri_lvi@icloud.com)
 */
export const resolveType = (sourceFile: SourceFile, type: Type): string => {
  const typeText = type.getText();

  try {
    // Accéder au compilateur TypeScript sous-jacent
    const compilerType = type.compilerType;
    const typeChecker = sourceFile.getProject().getTypeChecker().compilerObject;

    const fullyResolvedTypeText = typeChecker.typeToString(
      compilerType,
      undefined,
      TypeFormatFlags.InTypeAlias |
        TypeFormatFlags.WriteArrayAsGenericType |
        TypeFormatFlags.UseStructuralFallback |
        TypeFormatFlags.NoTruncation |
        TypeFormatFlags.WriteClassExpressionAsTypeLiteral |
        TypeFormatFlags.InElementType,
    );

    // #region Première  tentative: Si le type résolu est structurel
    // contient des objets et aucun import
    if (
      fullyResolvedTypeText !== typeText &&
      !fullyResolvedTypeText.includes('import(') &&
      (fullyResolvedTypeText.includes('{') ||
        fullyResolvedTypeText.length > typeText.length * 1.5)
    ) {
      return fullyResolvedTypeText;
    }
    // #endregion

    // #region Deuxième tentative: résoudre les alias et types importés
    const symbol = compilerType.symbol;

    // Pour les types aliasés (comme TransformArgs)
    if (symbol.flags & SymbolFlags.TypeAlias) {
      const aliasResolvedTypeText = typeChecker.typeToString(
        compilerType,
        undefined,
        TypeFormatFlags.InTypeAlias |
          TypeFormatFlags.WriteClassExpressionAsTypeLiteral |
          TypeFormatFlags.NoTruncation,
      );

      if (
        aliasResolvedTypeText !== typeText &&
        !aliasResolvedTypeText.includes('import(') &&
        aliasResolvedTypeText.includes('{')
      ) {
        return aliasResolvedTypeText;
      }
    }

    // Pour les types importés, essayer de résoudre le symbole aliasé
    if (symbol.flags & SymbolFlags.Alias) {
      const aliasedSymbol = typeChecker.getAliasedSymbol(symbol);
      if (aliasedSymbol && aliasedSymbol !== symbol) {
        const aliasedType = typeChecker.getTypeOfSymbolAtLocation(
          aliasedSymbol,
          aliasedSymbol.declarations?.[0] || sourceFile.compilerNode,
        );

        const resolvedAliasTypeText = typeChecker.typeToString(
          aliasedType,
          undefined,
          TypeFormatFlags.InTypeAlias |
            TypeFormatFlags.WriteClassExpressionAsTypeLiteral |
            TypeFormatFlags.NoTruncation,
        );

        if (
          resolvedAliasTypeText !== typeText &&
          !resolvedAliasTypeText.includes('import(') &&
          resolvedAliasTypeText.includes('{')
        ) {
          return resolvedAliasTypeText;
        }
      }
    }
    // #endregion

    // #region Troisième tentative: type apparent pour révéler la structure cachée
    const apparentType = typeChecker.getApparentType(compilerType);

    const apparentText = typeChecker.typeToString(
      apparentType,
      undefined,
      TypeFormatFlags.InTypeAlias |
        TypeFormatFlags.WriteClassExpressionAsTypeLiteral |
        TypeFormatFlags.UseStructuralFallback |
        TypeFormatFlags.NoTruncation,
    );

    if (
      apparentText !== typeText &&
      !apparentText.includes('import(') &&
      (apparentText.includes('{') || apparentText.length > typeText.length * 1.2)
    ) {
      return apparentText;
    }
    // #endregion

    // #region Quatrième tentative: forcer l'expansion structurelle
    const structuralTypeText = typeChecker.typeToString(
      compilerType,
      undefined,
      TypeFormatFlags.WriteClassExpressionAsTypeLiteral |
        TypeFormatFlags.UseStructuralFallback |
        TypeFormatFlags.InElementType |
        TypeFormatFlags.NoTruncation,
    );

    if (
      structuralTypeText !== typeText &&
      structuralTypeText !== fullyResolvedTypeText &&
      !structuralTypeText.includes('import(') &&
      structuralTypeText.includes('{')
    ) {
      return structuralTypeText;
    }
    // #endregion
  } catch (error) {
    console.warn(`Erreur lors de la résolution du type ${typeText} : `, error);
  }

  return typeText;
};

